<script lang="ts">
	import { run } from 'svelte/legacy';

	import { DropdownMenu } from 'bits-ui';
	import { flyAndScale } from '$lib/utils/transitions';
	import { getContext, onMount, tick } from 'svelte';

	import { config, user, tools as _tools, mobile } from '$lib/stores';
	import { getTools } from '$lib/apis/tools';

	import Dropdown from '$lib/components/common/Dropdown.svelte';
	import Tooltip from '$lib/components/common/Tooltip.svelte';
	import DocumentArrowUpSolid from '$lib/components/icons/DocumentArrowUpSolid.svelte';
	import Switch from '$lib/components/common/Switch.svelte';
	import GlobeAltSolid from '$lib/components/icons/GlobeAltSolid.svelte';
	import WrenchSolid from '$lib/components/icons/WrenchSolid.svelte';
	import CameraSolid from '$lib/components/icons/CameraSolid.svelte';
	import type { i18n as i18nType } from 'i18next';
	import type { Writable } from 'svelte/store';

	const i18n: Writable<i18nType> = getContext<Writable<i18nType>>('i18n');


	interface Props {
		screenCaptureHandler: Function;
		uploadFilesHandler: Function;
		onClose?: Function;
		children?: import('svelte').Snippet;
	}

	let {
		screenCaptureHandler,
		uploadFilesHandler,
		onClose = () => {},
		children
	}: Props = $props();

	let show = $state(false);


	const init = async () => {};
	run(() => {
		if (show) {
			init();
		}
	});
</script>

<Dropdown
	bind:show
	onchange={(e: CustomEvent) => {
		if (e.detail === false) {
			onClose();
		}
	}}
>
	<Tooltip content={$i18n.t('More')}>
		{@render children?.()}
	</Tooltip>

	{#snippet content()}
		<div >
			<DropdownMenu.Portal>
		<DropdownMenu.Content
				class="w-full max-w-[200px] rounded-xl px-1 py-1  border-gray-300/30 dark:border-gray-700/50 z-50 bg-white dark:bg-gray-850 dark:text-white shadow-sm"
				sideOffset={15}
				alignOffset={-8}
				side="top"
				align="start"			>
				{#if !$mobile}
					<DropdownMenu.Item
						class="flex gap-2 items-center px-3 py-2 text-sm  font-medium cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-800  rounded-xl"
						onclick={() => {
							screenCaptureHandler();
						}}
					>
						<CameraSolid />
						<div class=" line-clamp-1">{$i18n.t('Capture')}</div>
					</DropdownMenu.Item>
				{/if}

				<DropdownMenu.Item
					class="flex gap-2 items-center px-3 py-2 text-sm font-medium cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-800 rounded-xl"
					onclick={() => {
						uploadFilesHandler();
					}}
				>
					<DocumentArrowUpSolid />
					<div class="line-clamp-1">{$i18n.t('Upload Files')}</div>
				</DropdownMenu.Item>
			</DropdownMenu.Content>
	</DropdownMenu.Portal>
		</div>
	{/snippet}
</Dropdown>
